  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Combattant-Intuitif-(Oracle).html&quot; title=&quot;Combattant intuitif&quot;&gt;Combattant intuitif&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gardien-De-La-Communaut&#233;-(Oracle).html&quot; title=&quot;Gardien de la communaut&#233;&quot;&gt;Gardien de la communaut&#233;&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Halfelin.html&quot; title=&quot;Les halfelins&quot;&gt;Halfelin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gardien-Du-Savoir-Ancestral-(Oracle).html&quot; title=&quot;Gardien du savoir ancestral&quot;&gt;Gardien du savoir ancestral&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Elfe.html&quot; title=&quot;Les elfes&quot;&gt;Elfe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guide-Spirituel-(Oracle).html&quot; title=&quot;Guide spirituel&quot;&gt;Guide spirituel&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Oracle-Au-Sang-Noir-(Oracle).html&quot; title=&quot;Oracle au sang noir&quot;&gt;Oracle au sang noir&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Oracle-Des-&#201;toiles-(Oracle).html&quot; title=&quot;Oracle des &#233;toiles&quot;&gt;Oracle des &#233;toiles&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Oracle-Doublement-Maudit-(Oracle).html&quot; title=&quot;Oracle doublement maudit&quot;&gt;Oracle doublement maudit&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Oracle-Planaire-(Oracle).html&quot; title=&quot;Oracle planaire&quot;&gt;Oracle planaire&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Oracle-Poss&#233;d&#233;-(Oracle).html&quot; title=&quot;Oracle poss&#233;d&#233;&quot;&gt;Oracle poss&#233;d&#233;&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Oracle-R&#233;incarn&#233;-(Oracle).html&quot; title=&quot;Oracle r&#233;incarn&#233;&quot;&gt;Oracle r&#233;incarn&#233;&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Samsaran-(Race).html&quot; title=&quot;Les samsarans&quot;&gt;Samsaran&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Philosophe-&#201;clair&#233;-(Oracle).html&quot; title=&quot;Philosophe &#233;clair&#233;&quot;&gt;Philosophe &#233;clair&#233;&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Proph&#232;te-(Oracle).html&quot; title=&quot;Proph&#232;te&quot;&gt;Proph&#232;te&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Purificateur-(Oracle).html&quot; title=&quot;Purificateur&quot;&gt;Purificateur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aasimar-(Race).html&quot; title=&quot;Les aasimars&quot;&gt;Aasimar&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Shigenjo-(Oracle).html&quot; title=&quot;Shigenjo&quot;&gt;Shigenjo&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Tengu-(Race).html&quot; title=&quot;Les tengus&quot;&gt;Tengu&lt;/a&gt;) (MR)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;div style=&quot;float:right; padding: 0 0 8px 8px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; width:250px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;Il existe un arch&#233;type semblable chez les &lt;a class=&quot;pagelink&quot; href=&quot;Chercheur-(Ensorceleur).html&quot; title=&quot;Chercheur&quot;&gt;ensorceleurs&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;&lt;/td&gt;&lt;td style=&quot;height:30px&quot;&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:30px; cursor:pointer&quot; src=&quot;/images/pathfinder/wiki/ibase.png&quot; title=&quot;Cliquez pour afficher/cacher une d&#233;sambigu&#239;sation (homonymes, redirections, etc...)&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
